* { box-sizing: border-box; }
:root { --color-text: #172554; --color-surface: #ffffff; --color-accent: #1d4ed8; --space: 1rem; --radius: 0.75rem; }
body { margin: 0; color: var(--color-text); background: #f8fafc; font-family: system-ui, sans-serif; line-height: 1.55; }
a { color: inherit; }
button, input, select { font: inherit; }
:focus-visible { outline: 3px solid #1d4ed8; outline-offset: 3px; }
.page-shell { width: min(calc(100% - 2rem), 74rem); margin-inline: auto; }
.site-header { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: var(--space); padding: var(--space); }
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { scroll-behavior: auto !important; transition: none !important; } }
